// ─── File: HeapDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.heap;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class HeapDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Long-lived cache → survives collections → promoted to OLD gen.
        AccountCache cache = new AccountCache();
        cache.put(new Account("SAV2001", "Rajesh", new BigDecimal("1000000")));
        cache.put(new Account("CUR3001", "Priya",  new BigDecimal("250000")));

        StatementGenerator generator = new StatementGenerator();

        // Create LOTS of short-lived objects → born in EDEN → swept by minor GC.
        long shortLived = 0;
        for (Account a : cache.all()) {
            shortLived += generator.generate(a, 100_000); // many temporary lines
        }

        final long created = shortLived;
        log.info(() -> "Short-lived StatementLine objects created (young gen): " + created);
        log.info(() -> "Long-lived cached accounts (old gen candidates): " + cache.size());
        log.info(() -> "Cached Rajesh still alive: " + cache.get("SAV2001").getHolderName());
    }
}

// ─── Would be in Account.java (long-lived when cached) ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in StatementLine.java (short-lived) ───
class StatementLine {
    private final String text;
    StatementLine(String text) { this.text = text; }
    int length() { return text.length(); }
}

// ─── Would be in StatementGenerator.java ───
class StatementGenerator {
    // Each call creates many StatementLine objects that are discarded quickly.
    long generate(Account account, int lines) {
        long total = 0;
        for (int i = 0; i < lines; i++) {
            // Born in Eden; becomes garbage at end of each loop iteration.
            StatementLine line = new StatementLine(
                    account.getAccountId() + " line " + i + " bal=" + account.getBalance());
            total += line.length();
        }
        return total; // the lines themselves are now unreachable → young garbage
    }
}

// ─── Would be in AccountCache.java ───
class AccountCache {
    // Holds references for a long time → objects get promoted to Old gen.
    private final java.util.Map<String, Account> cache = new java.util.HashMap<>();
    void put(Account a) { cache.put(a.getAccountId(), a); }
    Account get(String id) { return cache.get(id); }
    Iterable<Account> all() { return cache.values(); }
    int size() { return cache.size(); }
}
